<script setup>
import { computed,onMounted,ref } from 'vue'
import { api } from './api'
const items=ref([]),loading=ref(false),error=ref(''),editing=ref(null),testResult=ref(null),testing=ref(false),search=ref(''),status=ref('all')
const blank=()=>({name:'',description:'',method:'POST',endpoint_url:'',headers:[],query:[],cookies:[],body_type:'json',body:{},response_mappings:[],timeout_seconds:15,active:true})
const filtered=computed(()=>items.value.filter(x=>(status.value==='all'||(status.value==='active'?x.active:!x.active))&&(!search.value||x.name.toLowerCase().includes(search.value.toLowerCase())||x.endpoint_url.toLowerCase().includes(search.value.toLowerCase()))))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—'}
async function load(){loading.value=true;error.value='';try{items.value=await api.httpApis()}catch(e){error.value=e.message}finally{loading.value=false}}
function addRow(key){editing.value[key].push({key:'',value:''})}function removeRow(key,i){editing.value[key].splice(i,1)}
function create(){editing.value=blank();testResult.value=null}function edit(x){editing.value=JSON.parse(JSON.stringify(x));testResult.value=null}
async function save(){error.value='';try{const payload=editing.value;const saved=payload.id?await api.updateHttpApi(payload.id,payload):await api.createHttpApi(payload);editing.value=saved;await load();return saved}catch(e){error.value=e.message;return null}}
async function test(){testing.value=true;testResult.value=null;try{const saved=await save();if(!saved?.id){testResult.value={success:false,error:error.value||'Unable to save API before testing'};return}testResult.value=await api.testHttpApi(saved.id);await load()}catch(e){testResult.value={success:false,error:e.message}}finally{testing.value=false}}
async function remove(x){if(!confirm(`Delete “${x.name}”?`))return;await api.deleteHttpApi(x.id);await load()}
onMounted(load)
</script>
<template><section class="http-page"><header><div><p class="eyebrow">Integrations</p><h1>HTTP APIs</h1><p>Connect and manage reusable outbound HTTP APIs for flows and automations.</p></div><button class="primary" @click="create">＋ Create API</button></header><div v-if="error" class="error">{{error}}</div><template v-if="!editing"><div class="toolbar"><select v-model="status"><option value="all">Any status</option><option value="active">Active</option><option value="inactive">Inactive</option></select><input v-model="search" placeholder="Search APIs…"/><button @click="load">↻ Refresh</button></div><div class="card"><div v-if="loading" class="empty">Loading…</div><div v-else-if="!filtered.length" class="empty">No HTTP APIs yet. Create your first reusable integration.</div><table v-else><thead><tr><th>API name</th><th>Method</th><th>Verified</th><th>Total calls</th><th>Success</th><th>Error</th><th>Last called</th><th>Actions</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td><strong>{{x.name}}</strong><small>{{x.endpoint_url}}</small></td><td><span class="method">{{x.method}}</span></td><td><span :class="['verified',x.verified?'yes':'no']">{{x.verified?'✓ Verified':'Not verified'}}</span></td><td>{{x.total_calls}}</td><td>{{x.total_success}}</td><td>{{x.total_error}}</td><td>{{fmt(x.last_called_at)}}</td><td><button @click="edit(x)">✎</button><button class="danger" @click="remove(x)">×</button></td></tr></tbody></table></div></template><template v-else><button class="back" @click="editing=null">← Back to HTTP APIs</button><div class="editor-grid"><main><section class="card form-card"><h2>API Details</h2><p>Enter the basic connection information for the API.</p><div class="details"><label>API Name<input v-model="editing.name" placeholder="e.g. Register customer"/></label><label>Method<select v-model="editing.method"><option v-for="m in ['GET','POST','PUT','PATCH','DELETE']" :key="m">{{m}}</option></select></label><label class="url">Endpoint URL<input v-model="editing.endpoint_url" placeholder="https://api.example.com/v1/resource"/></label></div></section><section class="card form-card"><h2>Request Data</h2><p>Configure headers, query parameters, cookies and request body.</p><div v-for="group in ['headers','query','cookies']" :key="group" class="pairs"><div class="pair-head"><strong>{{group.charAt(0).toUpperCase()+group.slice(1)}}</strong><button @click="addRow(group)">＋ Add</button></div><div v-for="(row,i) in editing[group]" :key="i" class="pair"><input v-model="row.key" placeholder="Key"/><input v-model="row.value" placeholder="Value / %variable%"/><button @click="removeRow(group,i)">×</button></div></div><div class="body"><label>Body Type<select v-model="editing.body_type"><option value="none">None</option><option value="json">JSON</option><option value="raw">Raw / Text</option><option value="form">Form URL Encoded</option></select></label><label>Body<textarea :value="typeof editing.body==='string'?editing.body:JSON.stringify(editing.body,null,2)" @input="editing.body=editing.body_type==='json'?(()=>{try{return JSON.parse($event.target.value)}catch{return $event.target.value}})():$event.target.value" placeholder='{"name":"%my_name%"}'></textarea></label></div></section><section class="card form-card"><div class="test-head"><div><h2>Test & Verify</h2><p>The current form is saved automatically before each test request.</p></div><button class="primary" :disabled="testing" @click="test">{{testing?'Sending…':'Send Test Request'}}</button></div><div v-if="testResult" :class="['response',testResult.success?'ok':'bad']"><div class="response-meta"><span v-if="testResult.status_code"><strong>Status</strong> {{testResult.status_code}}</span><span v-if="testResult.method"><strong>Method</strong> {{testResult.method}}</span><span v-if="testResult.duration_ms!=null"><strong>Duration</strong> {{testResult.duration_ms}} ms</span><span v-if="testResult.content_type"><strong>Content-Type</strong> {{testResult.content_type}}</span></div><div v-if="testResult.requested_url" class="response-url"><strong>Requested</strong> {{testResult.requested_url}}</div><div v-if="testResult.final_url" class="response-url"><strong>Final URL</strong> {{testResult.final_url}}</div><div v-if="testResult.error" class="response-error">{{testResult.error}}</div><pre>{{typeof testResult.response==='string'?testResult.response:JSON.stringify(testResult.response,null,2)}}</pre></div><div v-else class="response">Response will appear here after test…</div></section></main><aside><section class="card form-card"><h2>Automation</h2><p>This saved API becomes selectable from any WhatsApp or Telegram HTTP Request flow block.</p><label>Timeout (seconds)<input v-model.number="editing.timeout_seconds" type="number" min="1" max="120"/></label><label class="check"><input v-model="editing.active" type="checkbox"/> Active</label><button class="save" @click="save">Save API</button></section><section class="card form-card"><h2>Response Mapping</h2><p>Response-to-custom-field mapping will be used by the flow executor in the next stage.</p><div class="mapping-note">Example: <code>data.customer.id → customer_id</code></div></section></aside></div></template></section></template>
<style scoped>
.http-page{margin-left:220px;padding:34px 38px;min-height:100vh;background:#f4f7f6}.http-page>header{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:24px}.http-page h1{font-size:30px;margin:2px 0 5px}.http-page header p:last-child,.form-card>p{margin:0;color:#74867e}.eyebrow{text-transform:uppercase;color:#119052;font-size:11px;font-weight:800;letter-spacing:.08em;margin:0}.primary,.save{border:0;background:#168fd0;color:#fff;border-radius:9px;padding:11px 15px;font-weight:800;cursor:pointer}.primary:disabled{opacity:.65;cursor:wait}.toolbar{display:flex;gap:12px;margin-bottom:16px}.toolbar input{flex:1}.toolbar input,.toolbar select,.toolbar button,input,select,textarea{border:1px solid #d6e1db;background:#fff;border-radius:9px;padding:11px 12px}.toolbar select{min-width:180px}.card{background:#fff;border:1px solid #dce5df;border-radius:14px;overflow:hidden}.empty{padding:60px;text-align:center;color:#7c8c84}table{width:100%;border-collapse:collapse}th,td{padding:14px 16px;border-bottom:1px solid #e9efec;text-align:left}th{font-size:11px;text-transform:uppercase;color:#819088;background:#f8faf9}td small{display:block;color:#84928b;margin-top:4px;max-width:320px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}td button{border:1px solid #d8e2dd;background:#fff;border-radius:7px;padding:6px 9px;margin-right:5px}.danger{color:#b32f2f}.method{font-weight:800;color:#2773a0}.verified{font-size:11px;font-weight:800}.verified.yes{color:#07944d}.verified.no{color:#8b9691}.back{margin-bottom:15px;border:1px solid #d4dfda;background:#fff;border-radius:8px;padding:9px 12px}.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px}.editor-grid main,.editor-grid aside{display:flex;flex-direction:column;gap:18px}.form-card{padding:22px}.form-card h2{margin:0 0 5px;font-size:18px}.details{display:grid;grid-template-columns:1fr 150px;gap:12px;margin-top:18px}.details .url{grid-column:1/-1}label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;color:#53645b}label input,label select{font-weight:400;color:#17251e}.pairs{margin-top:20px}.pair-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.pair-head button{border:1px solid #b9d9ca;background:#fff;border-radius:7px;padding:6px 9px}.pair{display:grid;grid-template-columns:1fr 1.5fr 38px;gap:8px;margin-bottom:8px}.pair button{border:0;background:#fff0f0;color:#b33;border-radius:8px}.body{display:grid;gap:10px;margin-top:20px}.body textarea{min-height:150px;font-family:ui-monospace,monospace}.test-head{display:flex;justify-content:space-between;align-items:center}.response{margin-top:16px;padding:16px;background:#f3f6f8;border-radius:9px;min-height:80px;overflow:auto}.response.ok{background:#edfaf2}.response.bad{background:#fff0f0}.response-meta{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;margin-bottom:10px}.response-url{font-size:12px;overflow-wrap:anywhere;margin:5px 0}.response-error{color:#a22;font-weight:700;margin:10px 0}.response pre{margin:14px 0 0;white-space:pre-wrap;font-family:ui-monospace,monospace;font-size:12px}.check{flex-direction:row;align-items:center;margin:15px 0}.check input{width:auto}.save{width:100%;background:#16a05c}.mapping-note{margin-top:14px;padding:12px;background:#f4f8f6;border-radius:8px;color:#64756c}.error{padding:11px 13px;background:#fff0f0;color:#a22;border-radius:8px;margin-bottom:15px}@media(max-width:1050px){.editor-grid{grid-template-columns:1fr}}
</style>